var root="Assets/Animations/Player/";var c=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEditor.Animations.AnimatorController>(root+"PlayerDirectional.controller");
var dirs=new[]{"Front","FrontDiagonal","Side","BackDiagonal","Back"}; var positions=new[]{UnityEngine.Vector2.down,new UnityEngine.Vector2(1,-1),UnityEngine.Vector2.right,UnityEngine.Vector2.one,UnityEngine.Vector2.up};
var all=UnityEditor.AssetDatabase.LoadAllAssetsAtPath(root+"PlayerDirectional.controller");var idle=all.OfType<UnityEditor.Animations.AnimatorState>().Single(s=>s.name=="Idle_Default");var idleTree=(UnityEditor.Animations.BlendTree)idle.motion;
System.Action<UnityEditor.Animations.BlendTree,string> fill=(tree,prefix)=>{tree.blendType=UnityEditor.Animations.BlendTreeType.SimpleDirectional2D;tree.blendParameter="FacingX";tree.blendParameterY="FacingY";tree.useAutomaticThresholds=false;tree.children=System.Linq.Enumerable.Range(0,5).Select(i=>new UnityEditor.Animations.ChildMotion{motion=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.AnimationClip>(root+prefix+dirs[i]+".anim"),position=positions[i],timeScale=1}).ToArray();UnityEditor.EditorUtility.SetDirty(tree);};
fill(idleTree,"IdleDefault");
foreach(var name in new[]{"Dash","Roll"}){var state=c.layers[0].stateMachine.states.Select(x=>x.state).Single(s=>s.name==name);var tree=new UnityEditor.Animations.BlendTree{name=name+" Directions"};UnityEditor.AssetDatabase.AddObjectToAsset(tree,c);fill(tree,name);state.motion=tree;UnityEditor.EditorUtility.SetDirty(state);}UnityEditor.EditorUtility.SetDirty(c);UnityEditor.AssetDatabase.SaveAssets();return "Restored idle and created independent Dash and Roll trees";
